<script setup lang="ts">
import { computed, ref } from 'vue'
import { Download, Plus, RotateCcw, Unlink, Upload } from 'lucide-vue-next'
import type { Editor } from '../lib/editor'
import { clone, newId, type DesignComponent, type DesignTokenType, type Widget } from '../lib/model'
import { createComponentFromSelection, detachComponentInstance, insertComponentInstance, resetComponentOverrides, setComponentOverride, setComponentVariant, updateComponent } from '../lib/design-system'
import { validateDesignSystem } from '../lib/design-system'
import { exportDesignLibrary, importDesignLibrary, parseDesignLibrary, serializeDesignLibrary } from '../lib/design-library'
import { assetUrls, refreshAssets } from '../lib/resources'
import { browserProjectPackage } from '../lib/project-package'
import { call, desktop } from '../lib/backend'

const props=defineProps<{editor:Editor;canvas?:HTMLElement}>()
const editor=props.editor, project=computed(()=>editor.project.value), page=computed(()=>editor.page.value), system=computed(()=>project.value.designSystem), selected=computed(()=>page.value.widgets.filter(widget=>editor.selected.value.includes(widget.id))), components=computed(()=>Object.values(system.value?.components??{})), sets=computed(()=>Object.values(system.value?.tokenSets??{})), themes=computed(()=>Object.values(system.value?.themes??{})), instanceComponent=computed(()=>{const root=instanceRoot.value;return root?.componentInstance?system.value?.components[root.componentInstance.componentId]:undefined})
const message=ref(''),tokenName=ref(''),tokenValue=ref('#526273'),tokenType=ref<DesignTokenType>('color'),newTheme=ref(''),newSet=ref(''),targetSet=ref(''),newComponentName=ref(''),libraryVersion=ref('1.0.0'),file=ref<HTMLInputElement>(),instanceRoot=computed(()=>selected.value.find(widget=>widget.componentInstance)?.componentInstance?selected.value.find(widget=>widget.componentInstance):undefined),editingComponent=ref(''),componentDraft=ref('')
const tokenOptions=computed(()=>sets.value.flatMap(set=>Object.keys(set.tokens).map(name=>({value:`${set.id}.${name}`,label:`${set.name} / ${name}`}))))
function ensureSystem(){editor.mutate(p=>{p.designSystem??={version:1,tokenSets:{},themes:{},components:{},libraries:{}};if(!Object.keys(p.designSystem.tokenSets).length){p.designSystem.tokenSets.base={id:'base',name:'Base',tokens:{}};p.designSystem.themes.default={id:'default',name:'Default',tokenSets:['base']};p.designSystem.activeThemeId='default'}})}
function parseTokenValue(type:DesignTokenType,raw:string):unknown{if(type==='number'||type==='opacity')return Number(raw);if(type==='dimension'||type==='radius'){if(/^[-+]?(?:\d+\.?\d*|\.\d+)$/.test(raw))return Number(raw);return raw}if(type==='boolean')return raw==='true';if(['typography','shadow'].includes(type)||type==='color'&&/^[{[]/.test(raw)||type==='fontFamily'&&raw.trim().startsWith('[')){try{return JSON.parse(raw)}catch{throw Error(`Invalid ${type} JSON`)}}return raw}
function addToken(){if(!tokenName.value.trim())return;ensureSystem();const name=tokenName.value.trim();try{editor.mutate(p=>{const s=p.designSystem!,set=s.tokenSets[targetSet.value]??Object.values(s.tokenSets)[0]!;set.tokens[name]={$type:tokenType.value,$value:parseTokenValue(tokenType.value,tokenValue.value)}});tokenName.value='';message.value='Token added'}catch(error){message.value=String(error)}}
function changeToken(setId:string,name:string,type:DesignTokenType,event:Event){const raw=(event.target as HTMLInputElement).value;try{editor.mutate(p=>{const token=p.designSystem?.tokenSets[setId]?.tokens[name];if(!token)throw Error(`Unknown token ${setId}.${name}`);token.$value=parseTokenValue(type,raw)});message.value=`Updated token ${name}`}catch(error){message.value=String(error)}}
function addTokenSet(){if(!newSet.value.trim())return;ensureSystem();const id=newId('tokens');editor.mutate(p=>{p.designSystem!.tokenSets[id]={id,name:newSet.value.trim(),tokens:{}}});newSet.value=''}
function toggleThemeSet(themeId:string,setId:string,event:Event){const checked=(event.target as HTMLInputElement).checked;editor.mutate(p=>{const theme=p.designSystem!.themes[themeId]!;theme.tokenSets=checked?[...theme.tokenSets,setId]:theme.tokenSets.filter(id=>id!==setId)})}
function addTheme(){if(!newTheme.value.trim())return;ensureSystem();const id=newId('theme');editor.mutate(p=>{p.designSystem!.themes[id]={id,name:newTheme.value.trim(),tokenSets:Object.keys(p.designSystem!.tokenSets)};p.designSystem!.activeThemeId=id});newTheme.value=''}
function createComponent(){try{const component=createComponentFromSelection(page.value,editor.selected.value,{name:newComponentName.value.trim()||selected.value[0]?.name});editor.mutate(p=>{p.designSystem??={version:1,tokenSets:{},themes:{},components:{},libraries:{}};p.designSystem.components[component.id]=component});newComponentName.value='';message.value='组件已创建并关联源控件'}catch(error){message.value=String(error)}}
function insertComponent(component:DesignComponent){try{let x=80,y=80;const bounds=props.canvas?.getBoundingClientRect();if(bounds){x=Math.max(0,(bounds.width/2-editor.project.value.width/2));y=Math.max(0,(bounds.height/2-editor.project.value.height/2))}let root!:Widget;editor.mutate(()=>{root=insertComponentInstance(page.value,component,{x,y})});editor.selected.value=[root.id];message.value='组件实例已插入画布'}catch(error){message.value=String(error)}}
function overrideSelected(){const root=instanceRoot.value;if(!root?.componentInstance)return;const meta=root.componentInstance,source=Object.entries(meta.widgetIdMap).find(([,id])=>id===root.id)?.[0]??meta.rootWidgetId,component=system.value?.components[meta.componentId],sourceWidget=component?.widgets.find(widget=>widget.id===source);if(!sourceWidget)return;const property=Object.keys(sourceWidget.props)[0];if(!property)return;const value=window.prompt(`实例覆盖 ${property}`,String(root.props[property]??''));if(value===null)return;editor.mutate(()=>setComponentOverride(page.value,root.id,source,property,value));message.value=`已覆盖 ${property}`}
function applyVariantCombination(comboId:string){const root=instanceRoot.value,component=instanceComponent.value,variant=component?.variants?.combinations[comboId];if(!root?.componentInstance||!variant)return;try{editor.mutate(p=>setComponentVariant(p,root.id,clone(variant)));message.value=`Variant ${Object.entries(variant).map(([axis,value])=>`${axis}=${value}`).join(', ')}`}catch(error){message.value=String(error)}}
const variantCombinations=computed(()=>Object.entries(instanceComponent.value?.variants?.combinations??{}).map(([id,variant])=>({id,variant,label:Object.entries(variant).map(([axis,value])=>`${axis}=${value}`).join(', ')})))
const selectedVariantCombination=computed(()=>variantCombinations.value.find(item=>Object.keys(instanceComponent.value?.variants?.axes??{}).every(axis=>item.variant[axis]===instanceRoot.value?.componentInstance?.variant?.[axis]))?.id??'')
function resetOverrides(){const root=instanceRoot.value;if(!root)return;editor.mutate(()=>resetComponentOverrides(page.value,root.id));message.value='实例覆盖已重置'}
function detach(){const root=instanceRoot.value;if(!root)return;editor.mutate(()=>detachComponentInstance(page.value,root.id));message.value='实例已解除关联'}
function editComponent(component:DesignComponent){editingComponent.value=component.id;componentDraft.value=JSON.stringify(component,null,2)}
function saveComponentSource(){try{const component=JSON.parse(componentDraft.value) as DesignComponent;if(!component.id||!component.rootWidgetId||!Array.isArray(component.widgets))throw Error('Invalid component document');editor.mutate(p=>updateComponent(p,component));editingComponent.value='';message.value='Component source applied and instances synchronized'}catch(error){message.value=`Invalid component JSON: ${String(error)}`}}
function bytesToBase64(bytes:Uint8Array){let binary='';for(let offset=0;offset<bytes.length;offset+=0x8000)binary+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));return btoa(binary)}
async function exportLibrary(){ensureSystem();try{const assets=[];for(const asset of project.value.assets??[]){const url=assetUrls.value[asset.id];if(!url)throw Error(`Cannot read asset ${asset.id}`);const response=await fetch(url);if(!response.ok)throw Error(`Cannot read asset ${asset.id}`);const bytes=new Uint8Array(await response.arrayBuffer());assets.push({id:asset.id,name:asset.path.split(/[\\/]/).at(-1)??asset.id,mimeType:response.headers.get('content-type')??'application/octet-stream',bytesBase64:bytesToBase64(bytes)})}const data=exportDesignLibrary(project.value,{namespace:project.value.id,libraryVersion:libraryVersion.value,assets});const url=URL.createObjectURL(new Blob([serializeDesignLibrary(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`${project.value.name || 'design-library'}.hmidlib.json`;a.click();URL.revokeObjectURL(url);message.value=`Exported ${libraryVersion.value} library with ${assets.length} assets`}catch(error){message.value=String(error)}}
async function importLibrary(event:Event){const input=event.target as HTMLInputElement,selectedFile=input.files?.[0];try{if(!selectedFile)return;const document=parseDesignLibrary(await selectedFile.text());const componentCount=Object.keys(document.designSystem.components).length,tokenSetCount=Object.keys(document.designSystem.tokenSets).length,themeCount=Object.keys(document.designSystem.themes).length,existing=system.value?.libraries[document.namespace],existingComponents=existing?Object.keys(system.value?.components??{}).filter(id=>id.startsWith(`${existing.id}:`)).length:0,addedComponents=Math.max(0,componentCount-existingComponents),changedCandidates=Math.min(componentCount,existingComponents);const preview=`Import preview: ${document.namespace} v${document.libraryVersion}; ${addedComponents} new components, ${changedCandidates} possible changes (installed snapshot will remain unchanged), ${tokenSetCount} token sets, ${themeCount} themes, ${document.assets.length} assets. Import as a new snapshot?`;if(!window.confirm(preview))return;const before=JSON.stringify(project.value),candidate=clone(project.value);let prepared!:ReturnType<typeof importDesignLibrary>;prepared=importDesignLibrary(candidate,document);validateDesignSystem(candidate);const restored=[] as Array<{id:string;path:string}>;for(const asset of prepared.assets){const binary=atob(asset.bytesBase64),bytes=Uint8Array.from(binary,char=>char.charCodeAt(0));const record=desktop?await call<{id:string;path:string}>('import_asset_bytes',{name:asset.name,bytesBase64:asset.bytesBase64}):await browserProjectPackage.addAssetBytes(asset.name,bytes,project.value);restored.push({id:asset.id,path:record.path})}if(JSON.stringify(project.value)!==before)throw Error('Project changed during library asset import. No library changes were applied; retry the import.');editor.mutate(p=>{const result=importDesignLibrary(p,document);p.assets??=[];for(const asset of restored)if(!p.assets.some(item=>item.id===asset.id))p.assets.push(asset);if(result.namespace!==prepared.namespace)throw Error('Library namespace changed during import; retry the import.')});if(restored.length)await refreshAssets(project.value);message.value=`Imported ${componentCount} components and ${restored.length} assets as ${prepared.namespace} v${document.libraryVersion}`}catch(error){message.value=String(error)}finally{input.value=''}}
function bindToken(widget:Widget,property:string,event:Event){const value=(event.target as HTMLSelectElement).value;editor.mutate(()=>{widget.styleTokens??={};if(value)widget.styleTokens[property]=value;else delete widget.styleTokens[property]})}
</script>

<template><section class="design-system-panel" data-testid="design-system-panel"><header class="panel-title"><span>设计系统</span><span class="tiny-badge">本地</span></header><div class="design-system-scroll">
  <section class="design-system-section"><h4>主题</h4><label>当前主题<select :value="system?.activeThemeId??''" @change="editor.mutate(p=>{if(p.designSystem)p.designSystem.activeThemeId=($event.target as HTMLSelectElement).value})"><option v-for="theme in themes" :key="theme.id" :value="theme.id">{{theme.name}}</option></select></label><div class="inline-between"><input v-model="newTheme" aria-label="新主题名称" placeholder="主题名称"/><button class="text-button" @click="addTheme"><Plus :size="13"/>新增</button></div><p class="muted-copy">主题按顺序组合 token set；切换主题会同步预览与 Runner 样式。</p></section>
  <section class="design-system-section"><h4>设计令牌</h4><div class="inline-between"><input v-model="tokenName" aria-label="令牌名称" placeholder="例如 color.accent"/><select v-model="tokenType" aria-label="令牌类型"><option value="color">颜色</option><option value="dimension">尺寸</option><option value="number">数字</option><option value="radius">圆角</option><option value="fontFamily">字体</option><option value="shadow">阴影</option></select></div><div class="inline-between token-create"><select v-model="targetSet" aria-label="Token set"><option v-for="set in sets" :key="set.id" :value="set.id">{{set.name}}</option></select><input v-model="tokenValue" aria-label="令牌值"/><button class="text-button" @click="addToken"><Plus :size="13"/>添加</button></div><div v-for="set in sets" :key="set.id" class="token-set"><strong>{{set.name}}</strong><label v-for="(token,name) in set.tokens" :key="name" class="token-row"><code>{{name}}</code><input :value="Array.isArray(token.$value)?JSON.stringify(token.$value):typeof token.$value==='object'?JSON.stringify(token.$value):token.$value as any" :type="token.$type==='number'||token.$type==='opacity'?'number':'text'" @change="changeToken(set.id,name,token.$type,$event)"/></label></div><div v-if="system?.activeThemeId" class="theme-token-sets"><strong>Theme token sets</strong><label v-for="set in sets" :key="set.id" class="checkbox-label"><input type="checkbox" :checked="system.themes[system.activeThemeId]?.tokenSets.includes(set.id)" @change="toggleThemeSet(system.activeThemeId,set.id,$event)"/><span>{{set.name}}</span></label></div><div class="inline-between token-set-create"><input v-model="newSet" aria-label="Token set name" placeholder="Token set name"/><button class="text-button" @click="addTokenSet"><Plus :size="13"/>Add set</button></div><div v-for="widget in selected" :key="widget.id" class="token-binding-row"><strong>{{widget.name}}</strong><label v-for="property in ['color','background','borderColor','fontSize','borderRadius']" :key="property">{{property}}<select :value="widget.styleTokens?.[property]??''" @change="bindToken(widget,property,$event)"><option value="">未绑定</option><option v-for="tokenOption in tokenOptions" :key="tokenOption.value" :value="tokenOption.value">{{tokenOption.label}}</option></select></label></div></section>
  <section class="design-system-section"><div class="inline-between"><h4>组件与变体</h4><span class="tiny-badge">{{components.length}}</span></div><div class="inline-between"><input v-model="newComponentName" aria-label="组件名称" placeholder="组件名称"/><button class="text-button" :disabled="!selected.length" data-testid="create-component" @click="createComponent"><Plus :size="13"/>从选区创建</button></div><article v-for="component in components" :key="component.id" class="component-library-item"><div><strong>{{component.name}}</strong><small>{{component.widgets.length}} 个控件 · {{Object.keys(component.variants?.axes??{}).length}} 个变体轴</small></div><div class="inline-between"><button class="text-button" @click="insertComponent(component)">插入实例</button><button class="icon-button" title="编辑组件与变体" @click="editComponent(component)">编辑</button></div><textarea v-if="editingComponent===component.id" v-model="componentDraft" aria-label="Component source JSON" rows="10" class="component-source-json"/><div v-if="editingComponent===component.id" class="inline-between"><button class="text-button" @click="saveComponentSource">Apply source</button><button class="text-button" @click="editingComponent=''">Cancel</button></div></article><div v-if="instanceRoot" class="instance-actions"><strong>选中实例</strong><label v-if="variantCombinations.length">Variant combination<select aria-label="Variant combination" :value="selectedVariantCombination" @change="applyVariantCombination(($event.target as HTMLSelectElement).value)"><option value="" disabled>Select a valid combination</option><option v-for="item in variantCombinations" :key="item.id" :value="item.id">{{item.label}}</option></select></label><button class="text-button" data-testid="reset-component-overrides" @click="resetOverrides"><RotateCcw :size="13"/>重置覆盖</button><button class="text-button" @click="overrideSelected">覆盖源属性</button><button class="text-button" data-testid="detach-component" @click="detach"><Unlink :size="13"/>解除关联</button></div><p v-if="message" class="muted-copy" role="status">{{message}}</p><div class="inline-between library-actions"><button class="text-button" @click="exportLibrary"><Download :size="13"/>导出本地库</button><button class="text-button" @click="file?.click()"><Upload :size="13"/>导入本地库</button></div><input ref="file" hidden type="file" accept=".json,.hmidlib" @change="importLibrary"/></section>
</div></section></template>

<style scoped>.design-system-panel{display:flex;flex-direction:column;min-height:0;height:100%;background:var(--surface,#fff)}.design-system-scroll{overflow:auto;min-height:0;flex:1}.design-system-section{padding:14px;border-bottom:1px solid var(--line,#e5e7eb)}.design-system-section h4{margin:0 0 10px}.design-system-section label{margin:8px 0;font-size:11px}.design-system-section input,.design-system-section select{font-size:11px}.token-create{margin-top:7px}.token-set{margin-top:12px}.token-set>strong{display:block;margin-bottom:4px;font-size:11px}.token-row{display:grid!important;grid-template-columns:1fr 110px;align-items:center;gap:8px}.token-row code{font-size:10px;color:var(--muted,#737b86)}.token-binding-row{padding-top:8px}.token-binding-row>strong{display:block;font-size:11px;margin:0 0 7px}.component-library-item{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;border:1px solid var(--line,#e5e7eb);border-radius:5px;padding:9px;margin:7px 0}.component-library-item strong,.component-library-item small{display:block}.component-library-item small{font-size:10px;color:var(--muted,#737b86);margin-top:4px}.instance-actions{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin:12px 0;padding:9px;background:#f6f7f8;border-radius:5px}.instance-actions strong{width:100%;font-size:11px}.library-actions{margin-top:10px}.theme-token-sets{margin:10px 0}.theme-token-sets>strong{font-size:11px}.checkbox-label{display:flex;flex-direction:row!important;align-items:center;gap:7px}.checkbox-label input{width:14px}.token-set-create{margin:8px 0}.component-source-json{margin-top:8px;font-family:ui-monospace,monospace;font-size:10px;min-height:100px}</style>
